WFJ.Data.add("book", {
  ["d640c3f748926858"] = { "Nei tempi antichi, dopo che i Titani ebbero lasciato Azeroth, i loro figli, noti come terrigeni, continuarono a plasmare e custodire i recessi profondi del mondo. I terrigeni si curavano ben poco delle faccende delle razze che vivevano in superficie e desideravano soltanto scandagliare le oscure profondità della terra.", "." },
  ["d66b559d47b23e5f"] = { "La giovane e bella sacerdotessa Tyrande accettò di accompagnare i fratelli in nome di Elune. Benché Malfurion e Illidan amassero entrambi l'idealista sacerdotessa, il cuore di Tyrande apparteneva solo a Malfurion. Illidan provava risentimento per il nascente amore del fratello con Tyrande, ma sapeva che il suo dolore non era nulla in confronto alla sofferenza della sua dipendenza dalla magia.", "." },
  ["d688b87c9cd80936"] = { "Nel corso di sei anni, gli astuti Arathi superarono in strategia e in battaglia le tribù rivali. Dopo ogni vittoria, gli Arathi offrivano pace e uguaglianza ai popoli conquistati; in questo modo si guadagnarono la lealtà di coloro che avevano sconfitto. Alla fine la tribù degli Arathi arrivò a comprendere molte tribù diverse, e le file del suo esercito divennero sterminate.", "." },
  ["d6e106edcac2af51"] = { "Alexstrasza la Rossa, Ysera la Verde e Nozdormu il Bronzeo scesero sulle tranquille radure dei druidi e osservarono i frutti delle fatiche degli elfi della notte. Malfurion, divenuto un arcidruido di immenso potere, accolse i possenti draghi e raccontò loro della creazione del nuovo ⟦Well of Eternity=Pozzo dell'Eternità⟧.", "." },
})
